// SAMPLE ONLY – illustrates the shape of a FHIR CapabilityStatement.
// The real Halaxy answer comes from GET /metadata once you have an API key.
const r = (type, codes, params) => ({ type, interaction: codes.map(code => ({ code })), searchParam: params.map(name => ({ name })) });
return [{ json: { resourceType: 'CapabilityStatement', status: 'active', fhirVersion: '4.3.0', rest: [{ mode: 'server', resource: [
  r('Patient', ['read', 'search-type', 'create', 'update'], ['family', 'given', 'birthdate', 'email', 'phone', '_lastUpdated']),
  r('Appointment', ['read', 'search-type', 'create', 'update'], ['date', 'status', 'patient', 'practitioner', '_lastUpdated']),
  r('Referral', ['read', 'search-type', 'create'], ['patient', '_lastUpdated']),
  r('Invoice', ['read', 'search-type'], ['status', 'date', '_lastUpdated']),
  r('Practitioner', ['read', 'search-type'], ['name']),
  r('DocumentReference', ['create', 'patch'], [])
] }] } }];

const cs = $input.first().json;
const resources = (cs.rest && cs.rest[0] && cs.rest[0].resource) || [];
const focus = ['Patient', 'Appointment', 'Referral', 'ServiceRequest', 'Invoice', 'Slot', 'Schedule',
  'Practitioner', 'PractitionerRole', 'HealthcareService', 'Coverage', 'DocumentReference', 'Communication', 'Task'];
const rows = resources.map(r => ({
  resource: r.type,
  inFocus: focus.includes(r.type),
  canRead: (r.interaction || []).some(i => i.code === 'read'),
  canSearch: (r.interaction || []).some(i => i.code === 'search-type'),
  canCreate: (r.interaction || []).some(i => i.code === 'create'),
  canUpdate: (r.interaction || []).some(i => ['update', 'patch'].includes(i.code)),
  interactions: (r.interaction || []).map(i => i.code).join(', '),
  searchParams: (r.searchParam || []).map(s => s.name).join(', ')
}));
rows.sort((a, b) => (b.inFocus - a.inFocus) || a.resource.localeCompare(b.resource));
return rows.map(json => ({ json }));

// Clean the email and swap identifiers for tokens BEFORE anything is sent to the AI.
const m = $json;
const html = (m.body && m.body.content) || m.bodyPreview || '';
let text = html
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<br\s*\/?>|<\/p>|<\/div>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();

const tokens = {};
const counters = {};
function tokenise(re, label, clean = v => v) {
  text = text.replace(re, (match) => {
    const value = clean(match);
    const existing = Object.keys(tokens).find(k => k.startsWith(label) && tokens[k] === value);
    if (existing) return `[${existing}]`;
    counters[label] = (counters[label] || 0) + 1;
    const key = `${label}_${counters[label]}`;
    tokens[key] = value;
    return `[${key}]`;
  });
}
tokenise(/[\w.+-]+@[\w-]+(\.[\w-]+)+/g, 'EMAIL', v => v.toLowerCase());
tokenise(/\b\d{4}\s?\d{5}\s?\d(?:[\s\/-]?\d)?\b/g, 'MEDICARE', v => v.replace(/\D/g, ''));   // 10-11 digits
tokenise(/(?:\+?61\s?|\b0)4\d{2}[\s-]?\d{3}[\s-]?\d{3}\b/g, 'PHONE', v => v.replace(/\D/g, '').replace(/^61/, '0'));
tokenise(/(?:\+?61\s?|\b0)[2378][\s-]?\d{4}[\s-]?\d{4}\b/g, 'PHONE', v => v.replace(/\D/g, '').replace(/^61/, '0'));
tokenise(/\b\d{9}\b/g, 'IDNUM');   // e.g. NDIS numbers

return {
  json: {
    messageId: m.id,
    internetMessageId: m.internetMessageId || m.id,
    fromAddress: (m.from && m.from.emailAddress && m.from.emailAddress.address) || '',
    fromName: (m.from && m.from.emailAddress && m.from.emailAddress.name) || '',
    subject: m.subject || '',
    receivedAt: m.receivedDateTime || new Date().toISOString(),
    hasAttachments: !!m.hasAttachments,
    redactedText: text.slice(0, 8000),
    tokens            // stays inside n8n – never sent to the AI
  }
};

