// Never trust AI output blindly: parse, de-tokenise locally, then validate with plain rules.
const pre = $('Pre-process & Tokenise Identifiers').item.json;
const base = { ...pre };
delete base.redactedText;           // email text is not carried any further
const raw = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';
let r = null;
try { r = JSON.parse(raw.replace(/```json|```/g, '').trim()); } catch (e) { r = null; }
if (!r) {
  return { json: { ...base, status: 'exception', readyForHalaxy: false, missing: [], warnings: [],
    exceptionReason: 'AI output could not be parsed – please process manually' } };
}

const detok = t => (t ? (pre.tokens[String(t).replace(/[\[\]]/g, '')] || null) : null);
const clean = v => (typeof v === 'string' && v.trim() ? v.trim() : null);
const referral = {
  givenName: clean(r.givenName),
  familyName: clean(r.familyName),
  dateOfBirth: clean(r.dateOfBirth),
  phone: detok(r.clientPhoneToken),
  email: detok(r.clientEmailToken),
  medicare: detok(r.medicareToken),
  ndisNumber: detok(r.ndisToken),
  referrerName: clean(r.referrerName),
  referrerPractice: clean(r.referrerPractice),
  referrerProviderNumber: clean(r.referrerProviderNumber),
  referralDate: clean(r.referralDate),
  serviceRequested: r.serviceRequested || 'unclear',
  fundingType: r.fundingType || 'unclear',
  reasonSummary: clean(r.reasonSummary)
};

const SERVICES = ['psychology', 'exercise_physiology', 'occupational_therapy', 'personal_training', 'chronic_condition_management'];
const isDate = d => /^\d{4}-\d{2}-\d{2}$/.test(d || '') && !isNaN(new Date(d));
const missing = [];
if (!referral.givenName) missing.push('client given name');
if (!referral.familyName) missing.push('client family name');
if (!isDate(referral.dateOfBirth) || new Date(referral.dateOfBirth) > new Date()) missing.push('valid date of birth');
if (!referral.phone && !referral.email) missing.push('client phone or email');
if (!referral.referrerName) missing.push('referrer name');
if (!SERVICES.includes(referral.serviceRequested)) missing.push('service requested');

const warnings = [];
if (isDate(referral.referralDate) && (Date.now() - new Date(referral.referralDate)) / 86400000 > 365)
  warnings.push('Referral dated over 12 months ago – check it is still valid');
if (referral.fundingType === 'unclear') warnings.push('Funding type unclear');
if (pre.hasAttachments) warnings.push('Email has attachments – check referral letter is saved to the client file');
const confidence = typeof r.confidence === 'number' ? r.confidence : 0;

let status = 'complete', exceptionReason = null;
if (r.riskIndicators === true) {
  status = 'urgent';
  exceptionReason = 'POSSIBLE RISK INDICATOR – clinician to review today' + (r.riskNote ? ` (${r.riskNote})` : '');
} else if (missing.length) {
  status = 'incomplete';
  exceptionReason = 'Incomplete referral – missing: ' + missing.join(', ');
} else if (confidence < 0.7) {
  status = 'low_confidence';
  exceptionReason = `Low AI extraction confidence (${confidence}) – please verify`;
}

return { json: { ...base, referral, missing, warnings, aiConfidence: confidence, status, exceptionReason,
  readyForHalaxy: status === 'complete' } };

// Sample Halaxy client list (fictional people).
const DB = [
  { resourceType: 'Patient', id: 'demo-1001', name: [{ family: 'Ellis', given: ['Morgan'] }], birthDate: '1985-06-02',
    telecom: [{ system: 'phone', value: '0400 111 222' }, { system: 'email', value: 'morgan.ellis@example.com' }] },
  { resourceType: 'Patient', id: 'demo-1002', name: [{ family: 'Nguyen', given: ['Casey'] }], birthDate: '1990-01-01',
    telecom: [{ system: 'phone', value: '0400 333 444' }] },
  { resourceType: 'Patient', id: 'demo-1003', name: [{ family: 'Nguyen', given: ['Casey'] }], birthDate: '1990-01-01',
    telecom: [{ system: 'email', value: 'casey.n@example.com' }] }
];
const r = $('Parse & Validate Referral').item.json.referral;
const hits = DB.filter(p => p.name[0].family.toLowerCase() === (r.familyName || '').toLowerCase() && p.birthDate === r.dateOfBirth);
return { json: { resourceType: 'Bundle', type: 'searchset', total: hits.length, entry: hits.map(resource => ({ resource })) } };

// Score candidates. Only a single, strong match is auto-linked; anything else goes to staff.
const ref = $('Parse & Validate Referral').item.json;
const r = ref.referral;
const patients = ($json.entry || []).map(e => e.resource).filter(p => p && p.resourceType === 'Patient');
const norm = s => (s || '').toString().trim().toLowerCase();
const digits = s => (s || '').replace(/\D/g, '').replace(/^61/, '0');

const scored = patients.map(p => {
  const given = (p.name || []).flatMap(n => n.given || []).map(norm);
  const telecom = p.telecom || [];
  const phones = telecom.filter(t => ['phone', 'sms'].includes(t.system)).map(t => digits(t.value));
  const emails = telecom.filter(t => t.system === 'email').map(t => norm(t.value));
  let score = 0; const reasons = [];
  if (p.birthDate === r.dateOfBirth) { score += 2; reasons.push('DOB'); }
  if (given.includes(norm(r.givenName))) { score += 2; reasons.push('given name'); }
  else if (given.some(g => g[0] === norm(r.givenName)[0])) { score += 1; reasons.push('initial only'); }
  if (r.phone && phones.includes(digits(r.phone))) { score += 2; reasons.push('mobile'); }
  if (r.email && emails.includes(norm(r.email))) { score += 2; reasons.push('email'); }
  return { id: p.id, score, reasons: reasons.join(' + ') };
}).sort((a, b) => b.score - a.score);

const strong = scored.filter(s => s.score >= 4);
let matchStatus, patientId = null, exceptionReason = null;
if (patients.length === 0) {
  matchStatus = 'new';
} else if (strong.length === 1) {
  matchStatus = 'existing'; patientId = strong[0].id;
} else if (strong.length > 1) {
  matchStatus = 'ambiguous';
  exceptionReason = `Possible duplicate client records in Halaxy (${strong.length} strong matches) – link manually`;
} else {
  matchStatus = 'ambiguous';
  exceptionReason = 'A client with the same surname and DOB exists but name/contact differ – confirm before creating a new record';
}
return { json: { ...ref, matchStatus, patientId, matchCandidates: scored.slice(0, 3), exceptionReason } };

const src = (() => { try { return $('Capture New Patient ID').item.json; } catch (e) { return $('Match Existing Client').item.json; } })();
const r = src.referral;
return { json: {
  loggedAt: new Date().toISOString(),
  outcome: src.matchStatus === 'created' ? 'NEW CLIENT + REFERRAL' : 'REFERRAL ADDED TO EXISTING CLIENT',
  messageId: src.messageId,
  internetMessageId: src.internetMessageId,
  halaxyPatientId: src.patientId,
  clientInitials: (r.givenName || '?')[0] + (r.familyName || '?')[0],
  service: r.serviceRequested,
  funding: r.fundingType,
  referrerPractice: r.referrerPractice || '',
  aiConfidence: src.aiConfidence,
  warnings: (src.warnings || []).join('; '),
  exceptionReason: ''
} };

// One place that turns any problem into a clear, low-PHI review task.
const safe = n => { try { return $(n).item.json; } catch (e) { return null; } };
const base = safe('Capture New Patient ID') || safe('Match Existing Client') || safe('Parse & Validate Referral')
  || safe('Pre-process & Tokenise Identifiers') || {};
const r = base.referral || {};
let reason = $json.exceptionReason || base.exceptionReason;
if ($json.error) {
  const msg = typeof $json.error === 'string' ? $json.error : ($json.error.message || JSON.stringify($json.error));
  const afterPatient = base.patientId ? ` Client is in Halaxy (ID ${base.patientId}) – attach the referral manually.` : '';
  reason = 'Automation error: ' + String(msg).slice(0, 200) + '.' + afterPatient;
}
reason = reason || 'Unknown – please review';
const urgent = base.status === 'urgent';
const initials = (r.givenName ? r.givenName[0] : '?') + (r.familyName ? r.familyName[0] : '?');
const list = a => (a && a.length ? '<ul>' + a.map(x => `<li>${x}</li>`).join('') + '</ul>' : '<p>–</p>');
const html = `
  <h3 style="color:${urgent ? '#b00020' : '#333'}">${urgent ? 'URGENT – ' : ''}Referral needs review</h3>
  <p><b>Reason:</b> ${reason}</p>
  <p><b>Client initials:</b> ${initials} &nbsp; <b>Service:</b> ${r.serviceRequested || '–'} &nbsp; <b>Funding:</b> ${r.fundingType || '–'}</p>
  <p><b>Referrer:</b> ${r.referrerName || base.fromName || '–'} ${r.referrerPractice ? '(' + r.referrerPractice + ')' : ''}</p>
  <p><b>Missing:</b></p>${list(base.missing)}
  <p><b>Warnings:</b></p>${list(base.warnings)}
  <p><b>Possible Halaxy matches:</b></p>${list((base.matchCandidates || []).map(c => `ID ${c.id} – score ${c.score} (${c.reasons})`))}
  <p>The original email (subject: "${base.subject || ''}", received ${base.receivedAt || ''}) has been moved to the <b>Needs Review</b> folder.</p>`;
return { json: {
  messageId: base.messageId, urgent, subject: `${urgent ? '[URGENT] ' : ''}[Referral review] ${initials} – ${reason.slice(0, 70)}`,
  html,
  audit: { loggedAt: new Date().toISOString(), outcome: urgent ? 'URGENT REVIEW' : 'STAFF REVIEW', messageId: base.messageId,
    internetMessageId: base.internetMessageId, halaxyPatientId: base.patientId || '', clientInitials: initials,
    service: r.serviceRequested || '', funding: r.fundingType || '', referrerPractice: r.referrerPractice || '',
    aiConfidence: base.aiConfidence ?? '', warnings: (base.warnings || []).join('; '), exceptionReason: reason }
} };

// Finds the Xero organisation automatically - no tenant ID to copy/paste.
const want = ($('Config [02]').first().json.xeroOrgName || '').toLowerCase();
const orgs = $input.all().map(i => i.json).filter(o => o.tenantId);
if (!orgs.length) throw new Error('No Xero organisation is connected to this credential');
const org = orgs.find(o => want && (o.tenantName || '').toLowerCase().includes(want)) || orgs[0];
return [{ json: { tenantId: org.tenantId, tenantName: org.tenantName } }];

// Sample Halaxy invoices (fictional). Same references every run, so the 2nd run shows duplicate protection.
const inv = (id, num, date, total, payer, status = 'issued') => ({ resource: { resourceType: 'Invoice', id, status,
  identifier: [{ value: num }], date, recipient: { display: payer }, totalGross: { value: total, currency: 'AUD' } } });
return [{ json: { resourceType: 'Bundle', type: 'searchset', entry: [
  inv('demo-inv-1', 'INV-1001', '2026-10-20', 165.00, 'Jordan Pike'),
  inv('demo-inv-2', 'INV-1002', '2026-10-20', 193.99, 'Burnett Plan Management (demo)'),
  inv('demo-inv-3', 'INV-1003', '2026-10-21', 120.00, 'Riley Morgan'),
  inv('demo-inv-4', 'INV-1004', '2026-10-21', 88.00, 'Riley Morgan', 'cancelled')
] } }];

// FHIR Bundle -> one item per invoice, with only what Xero needs.
const bundle = $input.first().json;
const invoices = (bundle.entry || []).map(e => e.resource).filter(r => r && r.resourceType === 'Invoice');
const out = [];
for (const inv of invoices) {
  if (['cancelled', 'entered-in-error', 'draft'].includes(inv.status)) continue;
  const total = (inv.totalGross && inv.totalGross.value) ?? (inv.totalNet && inv.totalNet.value) ?? 0;
  if (!total) continue;
  const number = (inv.identifier && inv.identifier[0] && inv.identifier[0].value) || inv.id;
  out.push({ json: {
    halaxyInvoiceId: inv.id,
    reference: 'HLX-' + number,
    invoiceDate: (inv.date || new Date().toISOString()).slice(0, 10),
    total,
    payerName: ((inv.recipient && inv.recipient.display) || 'Unknown payer').replace(/"/g, '').trim(),
    halaxyStatus: inv.status
  }, pairedItem: { item: 0 } });
}
return out;

const inv = $('Flatten & Map Invoices').item.json;
const c = ($json.Contacts || [])[0];
return { json: { ...inv, contactId: c ? c.ContactID : null } };

const safe = n => { try { return $(n).item.json; } catch (e) { return null; } };
const inv = safe('Capture Contact ID') || $('Resolve Contact').item.json;
const existing = ($json.Invoices || []).filter(i => i.Status !== 'VOIDED' && i.Status !== 'DELETED');
return { json: { ...inv, alreadyInXero: existing.length > 0, existingXeroInvoiceId: existing[0] ? existing[0].InvoiceID : null,
  amountMismatch: existing[0] ? Math.abs(existing[0].Total - inv.total) > 0.009 : false } };

const inv = $('Flag Duplicates').item.json;
return { json: { loggedAt: new Date().toISOString(), reference: inv.reference, halaxyInvoiceId: inv.halaxyInvoiceId,
  xeroInvoiceId: $json.Invoices[0].InvoiceID, total: inv.total, result: 'CREATED (DRAFT)', note: '' } };

return { json: { loggedAt: new Date().toISOString(), reference: $json.reference, halaxyInvoiceId: $json.halaxyInvoiceId,
  xeroInvoiceId: $json.existingXeroInvoiceId, total: $json.total, result: 'SKIPPED – ALREADY IN XERO',
  note: $json.amountMismatch ? 'AMOUNT DIFFERS FROM XERO – CHECK' : '' } };

const safe = n => { try { return $(n).item.json; } catch (e) { return null; } };
const inv = safe('Flag Duplicates') || safe('Resolve Contact') || safe('Flatten & Map Invoices') || {};
const err = typeof $json.error === 'string' ? $json.error : ($json.error && $json.error.message) || 'Unknown error';
return { json: { subject: `[Xero sync] Failed: ${inv.reference || 'invoice fetch'}`,
  html: `<p>The Halaxy → Xero sync could not complete for <b>${inv.reference || 'the invoice batch'}</b>.</p>
         <p><b>Error:</b> ${String(err).slice(0, 300)}</p>
         <p>It will be retried automatically on the next hourly run. If this repeats, check the Xero connection / tenant ID.</p>` } };

// Three fictional appointments cancelled today.
const appt = (id, pid, pname, prac, service) => ({ resource: { resourceType: 'Appointment', id, status: 'cancelled',
  start: new Date().toISOString(), serviceType: [{ text: service }],
  participant: [{ actor: { reference: 'Patient/' + pid, display: pname } }, { actor: { reference: 'Practitioner/' + id, display: prac } }] } });
return [{ json: { resourceType: 'Bundle', entry: [
  appt('demo-a1', 'demo-2001', 'Riley Morgan', 'Hannah Lee', 'Exercise Physiology'),
  appt('demo-a2', 'demo-2002', 'Avery Brooks', 'Tom Walsh', 'Psychology'),
  appt('demo-a3', 'demo-2003', 'Jamie Collins', 'Hannah Lee', 'Occupational Therapy')
] } }];

const appts = ($input.first().json.entry || []).map(e => e.resource).filter(a => a && a.resourceType === 'Appointment');
const seen = new Set(); const out = [];
for (const a of appts) {
  const parts = a.participant || [];
  const pat = parts.find(p => p.actor && /Patient\//.test(p.actor.reference || ''));
  if (!pat) continue;                                   // internal blockers / meetings
  const patientId = pat.actor.reference.split('Patient/')[1];
  if (seen.has(patientId)) continue; seen.add(patientId);
  const prac = parts.find(p => p.actor && /Practitioner/.test(p.actor.reference || ''));
  out.push({ json: {
    patientId,
    service: (a.serviceType && a.serviceType[0] && (a.serviceType[0].text || (a.serviceType[0].coding || [])[0]?.display)) || a.description || 'appointment',
    practitionerFirstName: prac && prac.actor.display ? prac.actor.display.split(' ')[0] : null,
    cancelledApptStart: a.start
  }, pairedItem: { item: 0 } });
}
return out;

// Avery Brooks has already rebooked, so they are skipped.
const rebooked = ['demo-2002'];
const pid = $json.patientId;
return { json: { resourceType: 'Bundle', entry: rebooked.includes(pid) ? [{ resource: { resourceType: 'Appointment', status: 'booked' } }] : [] } };

// Sample client records. Emails go to YOUR address (Config → demoClientEmail) so you can see them arrive.
const pid = $('List Cancelled Clients').item.json.patientId;
const names = { 'demo-2001': ['Riley', 'Morgan'], 'demo-2002': ['Avery', 'Brooks'], 'demo-2003': ['Jamie', 'Collins'] };
const [given, family] = names[pid] || ['Client', 'Demo'];
return { json: { resourceType: 'Patient', id: pid, name: [{ given: [given], family }],
  telecom: [{ system: 'email', value: $('Config [03]').first().json.demoClientEmail }, { system: 'sms', value: '0400 000 000' }] } };

const c = $('List Cancelled Clients').item.json;
const p = $json;
const name = (p.name || [])[0] || {};
const telecom = p.telecom || [];
const email = (telecom.find(t => t.system === 'email') || {}).value || null;
const mobile = (telecom.find(t => ['sms', 'phone'].includes(t.system) && /^(\+?61|0)4/.test((t.value || '').replace(/\s/g, ''))) || {}).value || null;
return { json: {
  patientId: c.patientId,
  firstName: (name.given || [])[0] || 'there',
  contact: { email, mobile },                      // kept locally, never sent to the AI
  aiInput: { firstName: (name.given || [])[0] || 'there', service: c.service, practitionerFirstName: c.practitionerFirstName }
} };

const c = $('Minimum Data for AI').item.json;
let d = null;
try { d = JSON.parse((($json.choices || [])[0]?.message?.content || '').replace(/```json|```/g, '').trim()); } catch (e) {}
const issues = [];
if (!d) issues.push('AI draft unreadable');
else {
  if ((d.sms || '').length > 300) issues.push('SMS too long');
  if (/diagnos|depress|anxiety|pain|injur|condition/i.test((d.sms || '') + (d.emailBody || ''))) issues.push('Possible health detail in draft');
}
if (!c.contact.email && !c.contact.mobile) issues.push('No email or mobile on file');
return { json: { patientId: c.patientId, firstName: c.firstName, contact: c.contact, draft: d, issues } };

const drafts = $input.all().map((i, n) => ({ no: n + 1, ...i.json }));
const mask = v => v ? v.replace(/^(.{3}).*(.{3})$/, '$1•••$2') : '–';
const rows = drafts.map(d => `<tr><td>${d.no}</td><td>${d.firstName}</td><td>${mask(d.contact.email)}<br>${mask(d.contact.mobile)}</td>
  <td>${d.draft ? d.draft.sms : '–'}</td><td style="color:#b00020">${d.issues.join('<br>')}</td></tr>`).join('');
const html = `<p>${drafts.length} client(s) cancelled today and haven't rebooked. Please review the drafts below.</p>
  <table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>#</th><th>Client</th><th>Contact</th><th>Draft SMS</th><th>Flags</th></tr>${rows}</table>
  <p><b>Nothing is sent until you approve.</b> Drafts with flags are excluded automatically.</p>
  <p><a href="${$execution.resumeFormUrl}">Open the approval form</a> (approve all / exclude some / reject). No response within 18 hours = nothing sent.</p>`;
return [{ json: { drafts, html, count: drafts.length } }];

const f = $input.first().json;
const excluded = String(f['Exclude (row numbers, comma-separated)'] || '').split(',').map(s => parseInt(s.trim(), 10)).filter(Boolean);
const drafts = $('Bundle for Approval').first().json.drafts;
return drafts
  .filter(d => d.issues.length === 0 && d.draft && !(f.Decision === 'Approve except excluded' && excluded.includes(d.no)))
  .map(d => ({ json: { ...d, approvedBy: f['Approved by'], approvedAt: new Date().toISOString() } }));

const d = $('Release Approved Messages').item.json;
return { json: { loggedAt: new Date().toISOString(), halaxyPatientId: d.patientId,
  channel: d.contact.email ? 'email' : 'sms', approvedBy: d.approvedBy, result: 'SENT' } };

const f = $input.first().json;
return [{ json: { loggedAt: new Date().toISOString(), halaxyPatientId: '', channel: '',
  approvedBy: f['Approved by'] || '', result: f.Decision ? 'REJECTED BY APPROVER' : 'NO RESPONSE – NOTHING SENT' } }];

const e = $json;
const scrub = s => String(s || '')
  .replace(/[\w.+-]+@[\w-]+(\.[\w-]+)+/g, '[email]')
  .replace(/\+?\d[\d\s-]{7,}\d/g, '[number]')
  .replace(/\b\d{4}-\d{2}-\d{2}\b/g, '[date]')
  .slice(0, 400);
const wf = (e.workflow && e.workflow.name) || 'Unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = scrub(e.execution && e.execution.error && e.execution.error.message);
return { json: {
  subject: `[n8n ALERT] ${wf} failed at "${node}"`,
  html: `<p><b>Workflow:</b> ${wf}<br><b>Node:</b> ${node}<br><b>Error:</b> ${msg}</p>
         <p><a href="${(e.execution && e.execution.url) || '#'}">Open execution in n8n</a></p>`,
  log: { loggedAt: new Date().toISOString(), workflow: wf, node, error: msg, executionId: (e.execution && e.execution.id) || '' }
} };

const since = Date.now() - 24 * 3600 * 1000;
const fails = $input.all().map(i => i.json).filter(x => x && x.id && new Date(x.startedAt).getTime() >= since);
const byWf = {};
for (const f of fails) byWf[f.workflowId] = (byWf[f.workflowId] || 0) + 1;
const rows = Object.entries(byWf).map(([id, n]) => `<li>Workflow ${id}: ${n} failure(s)</li>`).join('');
return [{ json: {
  subject: fails.length ? `[n8n health] ${fails.length} failed run(s) in the last 24h` : '[n8n health] All automations ran cleanly',
  html: fails.length ? `<ul>${rows}</ul><p>Check the Error Log sheet for details.</p>` : '<p>No failed executions in the last 24 hours.</p>'
} }];
